3915	/* Try to parse the MSS option from the TCP header. Return 0 on failure, clamped
3916	 * value on success.
3917	 */
3918	static u16 tcp_parse_mss_option(const struct tcphdr *th, u16 user_mss)
3919	{
3920		const unsigned char *ptr = (const unsigned char *)(th + 1);
3921		int length = (th->doff * 4) - sizeof(struct tcphdr);
3922		u16 mss = 0;
3923	
3924		while (length > 0) {
3925			int opcode = *ptr++;
3926			int opsize;
3927	
3928			switch (opcode) {
3929			case TCPOPT_EOL:
3930				return mss;
3931			case TCPOPT_NOP:	/* Ref: RFC 793 section 3.1 */
3932				length--;
3933				continue;
3934			default:
3935				if (length < 2)
3936					return mss;
3937				opsize = *ptr++;
3938				if (opsize < 2) /* "silly options" */
3939					return mss;
3940				if (opsize > length)
3941					return mss;	/* fail on partial options */
3942				if (opcode == TCPOPT_MSS && opsize == TCPOLEN_MSS) {
3943					u16 in_mss = get_unaligned_be16(ptr);
3944	
3945					if (in_mss) {
3946						if (user_mss && user_mss < in_mss)
3947							in_mss = user_mss;
3948						mss = in_mss;
3949					}
3950				}
3951				ptr += opsize - 2;
3952				length -= opsize;
3953			}
3954		}
3955		return mss;
3956	}
3957	
3958	/* Look for tcp options. Normally only called on SYN and SYNACK packets.
3959	 * But, this can also be called on packets in the established flow when
3960	 * the fast version below fails.
3961	 */
3962	void tcp_parse_options(const struct net *net,
3963			       const struct sk_buff *skb,
3964			       struct tcp_options_received *opt_rx, int estab,
3965			       struct tcp_fastopen_cookie *foc)
3966	{
3967		const unsigned char *ptr;
3968		const struct tcphdr *th = tcp_hdr(skb);
3969		int length = (th->doff * 4) - sizeof(struct tcphdr);
3970	
3971		ptr = (const unsigned char *)(th + 1);
3972		opt_rx->saw_tstamp = 0;
3973		opt_rx->saw_unknown = 0;
3974	
3975		while (length > 0) {
3976			int opcode = *ptr++;
3977			int opsize;
3978	
3979			switch (opcode) {
3980			case TCPOPT_EOL:
3981				return;
3982			case TCPOPT_NOP:	/* Ref: RFC 793 section 3.1 */
3983				length--;
3984				continue;
3985			default:
3986				if (length < 2)
3987					return;
3988				opsize = *ptr++;
3989				if (opsize < 2) /* "silly options" */
3990					return;
3991				if (opsize > length)
3992					return;	/* don't parse partial options */
3993				switch (opcode) {
3994				case TCPOPT_MSS:
3995					if (opsize == TCPOLEN_MSS && th->syn && !estab) {
3996						u16 in_mss = get_unaligned_be16(ptr);
3997						if (in_mss) {
3998							if (opt_rx->user_mss &&
3999							    opt_rx->user_mss < in_mss)
4000								in_mss = opt_rx->user_mss;
4001							opt_rx->mss_clamp = in_mss;
4002						}
4003					}
4004					break;
4005				case TCPOPT_WINDOW:
4006					if (opsize == TCPOLEN_WINDOW && th->syn &&
4007					    !estab && net->ipv4.sysctl_tcp_window_scaling) {
4008						__u8 snd_wscale = *(__u8 *)ptr;
4009						opt_rx->wscale_ok = 1;
4010						if (snd_wscale > TCP_MAX_WSCALE) {
4011							net_info_ratelimited("%s: Illegal window scaling value %d > %u received\n",
4012									     __func__,
4013									     snd_wscale,
4014									     TCP_MAX_WSCALE);
4015							snd_wscale = TCP_MAX_WSCALE;
4016						}
4017						opt_rx->snd_wscale = snd_wscale;
4018					}
4019					break;
4020				case TCPOPT_TIMESTAMP:
4021					if ((opsize == TCPOLEN_TIMESTAMP) &&
4022					    ((estab && opt_rx->tstamp_ok) ||
4023					     (!estab && net->ipv4.sysctl_tcp_timestamps))) {
4024						opt_rx->saw_tstamp = 1;
4025						opt_rx->rcv_tsval = get_unaligned_be32(ptr);
4026						opt_rx->rcv_tsecr = get_unaligned_be32(ptr + 4);
4027					}
4028					break;
4029				case TCPOPT_SACK_PERM:
4030					if (opsize == TCPOLEN_SACK_PERM && th->syn &&
4031					    !estab && net->ipv4.sysctl_tcp_sack) {
4032						opt_rx->sack_ok = TCP_SACK_SEEN;
4033						tcp_sack_reset(opt_rx);
4034					}
4035					break;
4036	
4037				case TCPOPT_SACK:
4038					if ((opsize >= (TCPOLEN_SACK_BASE + TCPOLEN_SACK_PERBLOCK)) &&
4039					   !((opsize - TCPOLEN_SACK_BASE) % TCPOLEN_SACK_PERBLOCK) &&
4040					   opt_rx->sack_ok) {
4041						TCP_SKB_CB(skb)->sacked = (ptr - 2) - (unsigned char *)th;
4042					}
4043					break;
4044	#ifdef CONFIG_TCP_MD5SIG
4045				case TCPOPT_MD5SIG:
4046					/*
4047					 * The MD5 Hash has already been
4048					 * checked (see tcp_v{4,6}_do_rcv()).
4049					 */
4050					break;
4051	#endif
4052				case TCPOPT_FASTOPEN:
4053					tcp_parse_fastopen_option(
4054						opsize - TCPOLEN_FASTOPEN_BASE,
4055						ptr, th->syn, foc, false);
4056					break;
4057	
4058				case TCPOPT_EXP:
4059					/* Fast Open option shares code 254 using a
4060					 * 16 bits magic number.
4061					 */
4062					if (opsize >= TCPOLEN_EXP_FASTOPEN_BASE &&
4063					    get_unaligned_be16(ptr) ==
4064					    TCPOPT_FASTOPEN_MAGIC) {
4065						tcp_parse_fastopen_option(opsize -
4066							TCPOLEN_EXP_FASTOPEN_BASE,
4067							ptr + 2, th->syn, foc, true);
4068						break;
4069					}
4070	
4071					if (smc_parse_options(th, opt_rx, ptr, opsize))
4072						break;
4073	
4074					opt_rx->saw_unknown = 1;
4075					break;
4076	
4077				default:
4078					opt_rx->saw_unknown = 1;
4079				}
4080				ptr += opsize-2;
4081				length -= opsize;
4082			}
4083		}
4084	}

